import React, { useState } from 'react';
import Main from '../layouts/Main';
import posts from '../data/posts';

const Posts = () => {
  const [search, setSearch] = useState('');

  const filteredPosts = posts.filter((post) => {
    const searchLower = search.toLowerCase();
    return (
      post.title.toLowerCase().includes(searchLower)
      || post.tags.some((tag) => tag.toLowerCase().includes(searchLower))
      || post.description.toLowerCase().includes(searchLower)
    );
  });

  return (
    <Main title="Posts" description="A collection of my thoughts, notes, and writings.">
      <article className="post" id="posts">
        <header>
          <div className="title">
            <h2 style={{ fontSize: '2rem' }}>Posts</h2>
            <p style={{ fontSize: '1rem' }}>Explore thoughts, ideas, and technical writeups.</p>
          </div>
        </header>
        <div style={{ display: 'flex', justifyContent: 'flex-start', marginBottom: '2rem' }}>
          <input
            type="text"
            placeholder="Search posts..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{
              padding: '0.5rem 0.8rem',
              fontSize: '0.9rem',
              width: '40%',
              borderRadius: '5px',
              border: '1px solid #ccc',
              backgroundColor: 'transparent',
            }}
          />
        </div>
        <div>
          {filteredPosts.map((post) => (
            <div key={post.title} style={{ marginBottom: '2.5rem' }}>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                }}
              >
                <a
                  href={post.link}
                  target="_blank"
                  rel="noopener noreferrer"
                  style={{
                    fontWeight: 'bold',
                    fontSize: '1.4rem',
                    color: '#333',
                    textDecoration: 'none',
                  }}
                >
                  {post.title}
                </a>
                <span
                  style={{
                    fontSize: '0.95rem',
                    color: '#777',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {post.date}
                </span>
              </div>
              <div style={{ fontSize: '1rem', color: '#333', marginTop: '0.3rem' }}>
                {post.description}
              </div>
              <div style={{ fontSize: '0.95rem', color: '#666', marginTop: '0.3rem' }}>
                [{post.tags.join(', ')}]
              </div>
            </div>
          ))}
        </div>
      </article>
    </Main>
  );
};

export default Posts;
